import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:dollarden/core/split_engine.dart';

/// Parity with the server.
///
/// `split_golden.json` is generated by running the REAL Python engine
/// (`backend/app/budget/split.py`) over these fixtures. The Dart port
/// exists only so a paycheck preview can be instant and local, and a
/// preview that disagrees with what applying actually does is worse than
/// no preview at all — so every case is asserted to the cent, including
/// the ones the engine is supposed to REFUSE.
///
/// Regenerate after any change to the Python engine; see the command in
/// docs/06-budget-engine.md.
void main() {
  final file = File('test/split_golden.json');
  final cases = (jsonDecode(file.readAsStringSync()) as List)
      .cast<Map<String, dynamic>>();

  test('the golden file is present and non-trivial', () {
    expect(cases.length, greaterThan(10));
  });

  for (final c in cases) {
    final name = c['name'] as String;
    final gross = c['gross'] as int;
    final balances = (c['balances'] as Map).cast<String, dynamic>().map(
          (k, v) => MapEntry(k, v as int),
        );
    final rules = [
      for (final (i, r) in (c['rules'] as List).indexed)
        SplitRule(
          categoryId: (r as Map)['category_id'] as String,
          orderIndex: i + 1,
          ruleType: splitRuleTypeFrom(r['rule_type'] as String)!,
          params: (r['params'] as Map).cast<String, dynamic>(),
        )
    ];

    if (c.containsKey('error')) {
      test('rejects: $name', () {
        expect(
          () => applySplit(gross, rules, balances),
          throwsA(isA<SplitPlanError>()),
          reason: 'the server refuses this plan; the preview must too',
        );
      });
      continue;
    }

    final expected = c['expect'] as Map<String, dynamic>;
    test('matches the server: $name', () {
      final res = applySplit(gross, rules, balances);

      final wantAlloc = (expected['allocations'] as Map)
          .cast<String, dynamic>()
          .map((k, v) => MapEntry(k, v as int));
      expect(res.byCategory, wantAlloc);
      expect(res.remainingCents, expected['remaining'] as int);

      final wantUnfunded = [
        for (final u in (expected['unfunded'] as List))
          ((u as List)[0] as String, u[1] as int)
      ];
      expect(res.unfunded, wantUnfunded);

      // The property that matters most: no cent is invented or lost.
      expect(res.totalCents + res.remainingCents, gross,
          reason: 'the split must conserve the paycheck exactly');
    });
  }

  group('percentOf', () {
    test('rounds half up, like Decimal on the server', () {
      expect(percentOf(100005, '0.10'), 10001); // 10000.5 -> 10001
      expect(percentOf(100004, '0.10'), 10000); // 10000.4 -> 10000
      expect(percentOf(183733, '0.10'), 18373);
    });

    test('is exact where a double would not be', () {
      // 1999 * 0.29 is 579.71 in binary floating point territory.
      expect(percentOf(1999, '0.29'), 580);
      expect(percentOf(100000, '1'), 100000);
      expect(percentOf(100000, '0'), 0);
    });

    test('rejects a rate outside 0..1 rather than guessing', () {
      expect(() => percentOf(1000, '1.5'), throwsA(isA<SplitPlanError>()));
      expect(() => percentOf(1000, '-0.1'), throwsA(isA<SplitPlanError>()));
      expect(() => percentOf(1000, 'abc'), throwsA(isA<SplitPlanError>()));
      expect(() => percentOf(1000, ''), throwsA(isA<SplitPlanError>()));
    });
  });
}
